// Returns the maximum value in a non-empty slice.
// Precondition: a.len() >= 1
fn maxArray(a: &[i32]) -> i32 {
    // Start with the first element; this guarantees the result is an element of the array.
    let mut m = a[0];

    // Scan the rest and keep the largest seen so far.
    for &x in &a[1..] {
        if x > m {
            m = x;
        }
    }

    m
}

